def solution(*args, **kwargs):
    import sys

    s = sys.stdin.readline().rstrip('\n')

    # We just need to count all valid [ ... ] pairs, where [ occurs before ].
    # Each '[' can pair with any later ']', but each bracket is used at most once.
    # Optimal count = min(number of '[', number of ']') provided there is at least one '[' before a ']'.
    # We'll ensure order by scanning: each ']' pairs with closest unmatched '[' before it.

    open_count = 0
    pair_count = 0

    for ch in s:
        if ch == '[':
            open_count += 1
        elif ch == ']':
            if open_count > 0:
                open_count -= 1
                pair_count += 1

    if pair_count == 0:
        print(-1)
    else:
        print(pair_count)
